import Foundation
import PulseLoomCore

/// One of the original pieces shipped inside the app (App/Resources/Track-*.m4a, listed in tracks.json).
/// They are generated by Scripts/compose-music.py: no recordings, no third-party material.
struct BundledTrack: Codable, Identifiable, Equatable {
    var id: String
    var file: String
    var name: String
    var englishName: String
    var japaneseName: String
    var style: String
    var bpm: Int
    var seconds: Double

    func displayName(language: String = LoomLanguage.current) -> String {
        if language == "zh" { return name }
        if language == "ja", !japaneseName.isEmpty { return japaneseName }
        return englishName.isEmpty ? name : englishName
    }
    var url: URL? { Bundle.main.url(forResource: file, withExtension: "m4a") }
}

enum BundledMusic {
    static let tracks: [BundledTrack] = {
        guard let u = Bundle.main.url(forResource: "tracks", withExtension: "json"),
            let d = try? Data(contentsOf: u),
            let a = try? JSONDecoder().decode([BundledTrack].self, from: d)
        else { return [] }
        return a.filter { $0.url != nil }
    }()
    static func track(_ id: String) -> BundledTrack? { tracks.first { $0.id == id } }
}
